B=[]
def b(c,d,v,s=None): B.append((c,d,v,s))
big=lambda k,sub,ic='bolt': dict(t='big',k=k,sub=sub,ic=ic)
ti=lambda n,k: dict(t='title',n=n,k=k)
flow=lambda nodes,hot,sub='': dict(t='flow',nodes=nodes,hot=hot,sub=sub)
cmp_=lambda a,b_: dict(t='cmp',a=a,b=b_)
cards=lambda *it: dict(t='cards',items=list(it))
steps=lambda it,sub='': dict(t='steps',items=it,sub=sub)
term=lambda lines,pr=0: dict(t='term',lines=lines,pr=pr)
tree=lambda lines,hl: dict(t='tree',lines=lines,hl=hl)
code=lambda f,lines,hl: dict(t='code',f=f,lines=lines,hl=hl)
# ---------- GANCHO ----------
b("hook","Seu site ou painel tem *cara de feito por IA*? Degradê roxo, brilho em tudo e *emoji em cada botão*?",big('CARA DE IA?','degradê, brilho e emoji','ia'))
b("hook","Existe uma *skill gratuita* que conserta isso *passo a passo*. Hoje você vai *instalar e usar*, do zero.",big('UNSLOP','instalar e usar, do zero','gear'))
# ---------- 1 ----------
b("c1","*Capítulo um*: o que é a unslop.",ti(1,'O QUE É A UNSLOP'))
b("c1","A unslop é uma *skill* criada pelo designer *Damir Sokolovsky*. Ela transforma uma tela genérica numa interface *com personalidade própria*.",cmp_(('ANTES','tela genérica'),('DEPOIS','interface com personalidade')))
b("c1","Ela funciona em *três ferramentas*: o *Claude Code*, o *Codex* e o *Google Antigravity*.",cards(('CLAUDE CODE','/unslop'),('CODEX','$unslop'),('ANTIGRAVITY','pasta de skills')))
b("c1","A ideia central é simples: ela *conserta o acabamento* e *mantém o produto*. As funções, o conteúdo e a ordem das seções *continuam iguais*.",cmp_(('MUDA','tamanho, cor, texto, imagem'),('NÃO MUDA','funções e seções')))
b("c1","E tem um detalhe importante: tirar os defeitos é só *metade do trabalho*. Uma tela limpa, mas que serviria pra *qualquer produto*, vira só *outro modelo pronto*.",big('METADE','limpar não basta','bolt'))
b("c1","Por isso, toda execução termina com uma tela que *só esse produto* poderia ter.",big('SÓ SUA','a tela tem que ter dono','ia'))
# ---------- 2 ----------
b("c2","*Capítulo dois*: como reconhecer uma tela genérica.",ti(2,'OS SINAIS'))
b("c2","Segundo a skill, telas geradas sem cuidado *falham sempre do mesmo jeito*. Toda superfície *brilha*, e todo rótulo tem *um emoji*.",cards(('BRILHO','em toda superfície'),('EMOJI','em todo rótulo')))
b("c2","O espaçamento é *o que saiu na hora*, sem regra. E o texto *grita*, cheio de exclamação e palavras de propaganda.",cards(('ESPAÇAMENTO','sem regra'),('TEXTO','que grita')))
b("c2","A diferença entre o genérico e o bem feito está em *onde vai a riqueza*. O genérico espalha cor e efeito em *tudo*: fundo, botão, borda e rótulo.",flow(['FUNDO','BOTÃO','BORDA','RÓTULO'],0,'cor e efeito em tudo'))
b("c2","O bem feito deixa a moldura *quieta* e coloca a riqueza em *um ou dois momentos* de conteúdo: um objeto, um gráfico bonito, uma imagem.",cmp_(('MOLDURA','quieta'),('1 OU 2 MOMENTOS','ricos')))
# ---------- 3 ----------
b("c3","*Capítulo três*: instalação no Claude Code.",ti(3,'INSTALAR'))
b("c3","*Passo um*: abra o terminal e *clone o repositório* da skill.",term(['$ git clone https://github.com/heydamir/unslop']),"Passo um: abra o terminal e clone o repositório da iskil.")
b("c3","*Passo dois*: crie a *pasta de skills* do Claude, dentro da sua pasta pessoal, se ela ainda não existir.",term(['$ mkdir -p ~/.claude/skills']))
b("c3","*Passo três*: *copie a pasta da skill* pra dentro dela.",term(['$ cp -r unslop/skills/unslop ~/.claude/skills/']))
b("c3","Pronto: agora a skill vale para *todos os seus projetos*.",tree([('~/.claude/',0),('skills/',1),('unslop/',2),('SKILL.md',3)],2))
b("c3","Quer usar em *um projeto só*? Copie para a pasta *ponto claude, skills*, dentro *desse projeto*.",tree([('meu-projeto/',0),('.claude/',1),('skills/',2),('unslop/',3)],3))
b("c3","No *Codex*, você pode pedir pra ele instalar direto do repositório, ou copiar na mão para a pasta *ponto agents, skills*.",cmp_(('CODEX','~/.agents/skills'),('PROJETO','.agents/skills')))
b("c3","No *Antigravity*, a pasta é outra: *ponto gemini, antigravity, skills*.",tree([('~/.gemini/',0),('antigravity/',1),('skills/',2),('unslop/',3)],3))
# ---------- 4 ----------
b("c4","*Capítulo quatro*: o que instalar a mais.",ti(4,'EXTRAS OPCIONAIS'))
b("c4","Para o básico, *não precisa de mais nada*. Mas duas funções pedem ferramentas extras.",big('OPCIONAL','só para duas funções','gear'))
b("c4","Para *capturar um site que está no ar*, ou *criar o vídeo* do antes e depois, instale o *Playwright* e o navegador dele, na pasta do projeto.",term(['$ npm install -D playwright','$ npx playwright install chromium']),"Para capturar um site que está no ar, ou criar o vídeo do antes e depois, instale o Plêiráit e o navegador dele, na pasta do projeto.")
b("c4","E o vídeo ainda precisa do *ffmpeg* instalado no computador.",cards(('PLAYWRIGHT','captura e vídeo'),('FFMPEG','só para o vídeo')),"E o vídeo ainda precisa do éfe éfe êmpeg instalado no computador.")
# ---------- 5 ----------
b("c5","*Capítulo cinco*: como chamar a skill.",ti(5,'COMO USAR'))
b("c5","No Claude Code, digite *barra unslop* e diga *o que você quer*.",term(['> /unslop this dashboard']),"No Clód Côudi, digite barra ânslóp e diga o que você quer.")
b("c5","Dá pra apontar *uma parte* de um site que já está no ar, passando o *endereço*.",term(['> /unslop the hero of https://example.com']),"Dá pra apontar uma parte de um site que já está no ar, passando o endereço.")
b("c5","E dá pra pedir *o vídeo junto*, pra postar depois.",term(['> /unslop my landing page','  and make the story video']),"E dá pra pedir o vídeo junto, pra postar depois.")
b("c5","No Codex, o comando começa com *cifrão*. E nos dois, você também pode *pedir com as suas palavras*: o agente encontra a skill sozinho.",cmp_(('COMANDO','/unslop ou $unslop'),('OU','peça com suas palavras')))
# ---------- 6 ----------
b("c6","*Capítulo seis*: o que acontece quando ela roda.",ti(6,'O PROCESSO'))
b("c6","São *oito etapas*. A primeira é *olhar a tela*: achar os arquivos e, se possível, *tirar uma captura*, pra julgar o que a pessoa *vê*, e não só o código.",flow(['OLHAR','AUDITAR','DECIDIR','DIREÇÃO'],0,'julgar o que a pessoa vê'))
b("c6","Se você só tem *um link*, ela salva a página e trabalha numa *cópia*. Se só tem *uma imagem*, ela *reconstrói a tela* num arquivo antes.",cmp_(('SÓ UM LINK','salva e copia'),('SÓ UMA IMAGEM','reconstrói a tela')))
b("c6","A segunda etapa é a *auditoria*: listar *cada sinal* encontrado, uma linha por sinal, dizendo *onde ele está*.",flow(['OLHAR','AUDITAR','DECIDIR','DIREÇÃO'],1,'cada sinal, com o lugar'))
b("c6","A terceira é *decidir o tamanho da mudança*. Se há *muitos sinais*, roda o processo completo.",flow(['OLHAR','AUDITAR','DECIDIR','DIREÇÃO'],2,'quanto mudar'))
b("c6","Se há *poucos*, entra o *modo polimento*: corrige só o que achou e *mantém* a paleta, a letra e o desenho da página.",cmp_(('MUITOS SINAIS','processo completo'),('POUCOS','modo polimento')))
b("c6","E se *não há problema*, ela *diz isso claramente* e sugere, no máximo, *dois ou três ajustes pequenos*. Ela nunca muda uma tela boa só pra ficar diferente.",big('TELA BOA?','ela avisa e não refaz','ia'))
b("c6","A quarta etapa é *definir a direção e parar*. Ela mostra a auditoria e a direção, e *espera a sua resposta* antes de editar.",flow(['OLHAR','AUDITAR','DECIDIR','DIREÇÃO'],3,'mostra e espera você'))
b("c6","Isso importa, porque mudar a direção depois significa *refazer tudo*.",big('ESPERA','você aprova antes','gear'))
b("c6","Depois vêm as *nove passadas*, a *conferência*, o *relatório* e, se você pedir, o *vídeo*.",flow(['9 PASSADAS','CONFERIR','RELATAR','VÍDEO'],0,'etapas cinco a oito'))
# ---------- 7 ----------
b("c7","*Capítulo sete*: a direção, em cinco linhas.",ti(7,'A DIREÇÃO'))
b("c7","Antes de mexer em qualquer coisa, a skill escreve *cinco linhas curtas*. Elas saem do que a página diz que o produto faz, *nunca do que está na moda*.",big('5 LINHAS','do produto, não da moda','bolt'))
b("c7","*Produto*: o que ele faz e *pra quem*, em uma frase simples.",steps(['1  PRODUTO','2  CARÁTER','3  MUNDO','4  MOMENTOS','5  ASSINATURA'],'o que faz e para quem'))
b("c7","*Caráter*: duas ou três palavras concretas. Palavras como *limpo, moderno e minimalista* são *proibidas*, porque descrevem qualquer modelo pronto.",cmp_(('VALE','calmo, exato, caloroso'),('NÃO VALE','limpo, moderno')))
b("c7","*Mundo*: o lugar ou material de onde o produto vem. Um aplicativo de notas vive perto de *papel e tinta*. Um de viagem, perto de *mapas*.",cards(('NOTAS','papel e tinta'),('VIAGEM','mapas e janela'),('MONITORAMENTO','instrumentos')))
b("c7","*Momentos*: um ou dois lugares onde a tela ganha *cor rica e detalhe*, como um gráfico em que *cada cor significa algo*.",big('MOMENTOS','um ou dois, não dez','ia'))
b("c7","*Assinatura*: *um* detalhe pequeno que só esse produto teria, usado sempre. *Um detalhe*, não cinco.",big('1 DETALHE','a assinatura do produto','gear'))
b("c7","E se o produto já tem *marca de verdade*, como logotipo ou cor própria, a skill *mantém* e monta a direção em volta dela.",cmp_(('MARCA REAL','fica'),('DEGRADÊ E BRILHO','saem')))
# ---------- 8 ----------
b("c8","*Capítulo oito*: as nove passadas, na ordem.",ti(8,'AS 9 PASSADAS'))
b("c8","A ordem é fixa: *espaçamento, cor, ícones, texto, tipografia, layout, detalhes, imagens e movimento*. Cada passada cobre *a tela inteira* antes da próxima.",steps(['1 ESPAÇAMENTO','2 COR','3 ÍCONES','4 TEXTO','5 TIPOGRAFIA'],'depois: layout, detalhes, imagens, movimento'))
b("c8","O *espaçamento* vem primeiro, porque tudo se lê diferente quando o ritmo está certo. Tudo fica numa grade de *quatro pixels*.",big('GRADE DE 4','margens em múltiplos de 4','bolt'))
b("c8","Coisas iguais têm *tamanho igual*. E o espaço *dentro* de um grupo é menor que o espaço *entre* grupos.",cmp_(('DENTRO DO GRUPO','menos espaço'),('ENTRE GRUPOS','mais espaço')))
b("c8","Na *cor*, tudo parte de *uma escala de neutros*: fundo, superfícies, bordas e texto. E *um destaque só*, usado raramente.",cards(('NEUTROS','fundo, borda, texto'),('1 DESTAQUE','ação principal')))
b("c8","Saem os *degradês de cor*, o texto em degradê, os brilhos coloridos e as bordas neon.",steps(['SEM DEGRADÊ DE COR','SEM BRILHO COLORIDO','SEM BORDA NEON'],'o que sai na passada de cor'))
b("c8","E o destaque com texto em cima precisa de *contraste de quatro e meio para um*, pra dar pra ler.",big('4,5 : 1','contraste mínimo do destaque','gear'))
b("c8","Nos *ícones*, cada emoji usado como ícone vira um *ícone de linha*, de *um conjunto só*, com um tamanho e um traço.",cmp_(('EMOJI','sai'),('ÍCONE DE LINHA','um conjunto só')))
b("c8","No *texto*, o título diz o que o produto faz *e pra quem*, usando os fatos que já estão na página, *sem inventar*.",big('TÍTULO','o que faz e para quem','ia'))
b("c8","*Nada de exclamação*, nada de saudação com emoji, e nada de palavras de propaganda, como *revolucionário* ou *mágico*.",steps(['SEM EXCLAMAÇÃO','SEM SAUDAÇÃO','SEM PROPAGANDA'],'regras do texto'))
b("c8","Promessas que não dá pra conferir, como *dez vezes mais rápido*, só ficam se você *confirmar que são reais*. Senão, saem.",cmp_(('CONFIRMOU?','fica, sem exagero'),('NÃO CONFIRMOU','sai')))
b("c8","Na *tipografia*, poucas letras e *dois pesos*. A hierarquia vem do *tamanho e da cor*, não do negrito.",cards(('2 PESOS','400 e 500'),('HIERARQUIA','tamanho e cor')))
b("c8","E nada de rótulo todo em *maiúsculas* com letras espaçadas: vira texto normal.",cmp_(('NAVIGATION','antes'),('Navigation','depois')))
b("c8","No *layout*, as seções e a ordem *ficam*. O que pode mudar é o alinhamento e a proporção, pra tela ficar mais clara.",big('LAYOUT','seções ficam, proporção melhora','bolt'))
b("c8","E o topo da página fica com *uma ação principal* e, no máximo, *uma secundária*.",cmp_(('1 AÇÃO','principal'),('NO MÁXIMO 1','secundária')))
b("c8","As últimas passadas cuidam dos *detalhes*, das *imagens* e do *movimento*.",steps(['7 DETALHES','8 IMAGENS','9 MOVIMENTO'],'as três últimas'))
# ---------- 9 ----------
b("c9","*Capítulo nove*: imagens e custos.",ti(9,'IMAGENS E CUSTOS'))
b("c9","Na passada de imagens, a skill prefere *mostrar o seu produto de verdade*, em vez de uma forma brilhante genérica.",cmp_(('SEU PRODUTO','de verdade'),('FORMA GENÉRICA','não')))
b("c9","Quando o topo precisa de uma cena ou de um objeto, ela *pode gerar uma imagem* por um serviço externo.",big('IMAGEM','gerada só se precisar','ia'))
b("c9","Se nenhum serviço estiver conectado, ela *oferece conectar um*. E atenção: ela *mostra o pedido* e *pergunta antes* de cada geração paga.",steps(['MOSTRA O PEDIDO','PERGUNTA ANTES','SÓ ENTÃO GERA'],'toda geração paga'))
b("c9","Ou seja: o *custo* de imagem é do serviço que você escolher, e *você decide* cada vez.",big('VOCÊ DECIDE','cada geração paga','gear'))
# ---------- 10 ----------
b("c10","*Capítulo dez*: conferência e relatório.",ti(10,'CONFERIR'))
b("c10","Depois das passadas, a skill *roda uma lista de checagem*, mostra a tela de novo e *compara com a auditoria*.",flow(['CHECAGEM','NOVA CAPTURA','COMPARA'],2,'com a lista da auditoria'))
b("c10","Qualquer item que *ainda esteja na lista* é corrigido.",big('SOBROU?','corrige de novo','bolt'))
b("c10","No fim, ela entrega um *relatório*: a direção, algumas linhas por passada sobre *o que mudou*, e qualquer pedido de imagem que escreveu.",cards(('DIREÇÃO','as 5 linhas'),('PASSADAS','o que mudou'),('IMAGENS','pedidos escritos')))
b("c10","E ela tenta ser *rápida*: mostra a tela pra conferir *no máximo três vezes*.",big('3 VEZES','no máximo, para conferir','gear'))
# ---------- 11 ----------
b("c11","*Capítulo onze*: o vídeo do antes e depois.",ti(11,'O VÍDEO'))
b("c11","Se você pedir, a skill cria um *vídeo quadrado*, de *menos de dez segundos*, da sua tela se consertando.",big('< 10 S','vídeo quadrado, pronto pra postar','ia'))
b("c11","Peça o vídeo *logo no começo*: assim ela registra *cada passada* enquanto trabalha.",cmp_(('PEDIU NO COMEÇO','registra cada passada'),('PEDIU DEPOIS','monta no fim')))
b("c11","Lembre: o vídeo precisa do *Playwright* e do *ffmpeg* instalados.",cards(('PLAYWRIGHT','obrigatório'),('FFMPEG','obrigatório')),"Lembre: o vídeo precisa do Plêiráit e do éfe éfe êmpeg instalados.")
# ---------- 12 ----------
b("c12","*Capítulo doze*: como treinar antes de usar no seu projeto.",ti(12,'TREINAR'))
b("c12","O repositório traz *duas telas de exemplo*, feitas de propósito com todos os defeitos: um *painel* e um *topo de página*.",tree([('unslop/',0),('examples/',1),('dashboard.html',2),('hero.html',2)],1))
b("c12","Abra a pasta do repositório no Claude Code e rode a skill *num dos exemplos*.",term(['$ cd unslop','> /unslop examples/dashboard.html']),"Abra a pasta do repositório no Clód Côudi e rode a iskil num dos exemplos.")
b("c12","Leia a *auditoria* e a *direção* com calma. É ali que você aprende a *enxergar os sinais* nas suas próprias telas.",steps(['LEIA A AUDITORIA','LEIA A DIREÇÃO','SÓ DEPOIS APROVE'],'aprenda a enxergar'))
# ---------- 13 ----------
b("c13","*Capítulo treze*: cuidados e boas práticas.",ti(13,'CUIDADOS'))
b("c13","*Primeiro*: use *controle de versão*. A skill edita os seus arquivos, então salve o estado antes, pra poder *voltar atrás*.",term(['$ git add -A','$ git commit -m "antes do unslop"']),"Primeiro: use controle de versão. A iskil edita os seus arquivos, então salve o estado antes, pra poder voltar atrás.")
b("c13","*Segundo*: *responda a direção com atenção*. Se o caráter ou o mundo não combinam com o seu produto, *corrija antes* de aprovar.",big('DIREÇÃO','corrija antes de aprovar','bolt'))
b("c13","*Terceiro*: *confira os textos*. A skill não deve inventar fatos, mas quem conhece o produto é *você*.",big('TEXTOS','confira os fatos','ia'))
b("c13","*Quarto*: a licença é *Creative Commons com atribuição*. Pode usar, mudar e compartilhar, até comercialmente, desde que *dê o crédito* ao autor e ligue para o repositório.",cmp_(('PODE','usar, mudar, compartilhar'),('DEVE','dar o crédito')))
b("c13","*Quinto*: *comece por uma tela*. A mais importante. Veja o resultado, e só então siga para as outras.",steps(['1  UMA TELA','2  CONFIRA','3  AS OUTRAS'],'uma de cada vez'))
# ---------- RESUMO + CTA ----------
b("fim","*Resumindo*: clone o repositório, copie a pasta para as suas skills e digite *barra unslop*. Ela *audita*, propõe uma *direção*, espera você, e conserta em *nove passadas*.",steps(['CLONAR E COPIAR','/UNSLOP','APROVAR A DIREÇÃO','9 PASSADAS'],'o caminho completo'),"Resumindo: clone o repositório, copie a pasta para as suas iskils e digite barra ânslóp. Ela audita, propõe uma direção, espera você, e conserta em nove passadas.")
b("fim","Quer criar vídeos como esse? Comente *ARQUIVO* que vou te enviar a mesma *skill* que eu utilizo para criar vídeos assim,",dict(t='cta2'))
b("fim","mas você precisa estar *me seguindo* para a mensagem chegar.",dict(t='cta1'))
